CREATE OR REPLACE PROCEDURE sp(para_Num_of_Pieces integer, para_Performance_ID integer, para_Attendance integer, para_integer text)
LANGUAGE plpgsql
AS $$
DECLARE
  rec RECORD;
  var1 integer;
  var2 text;
BEGIN
  var1 := para_Num_of_Pieces * 2;
  var2 := para_Performance_ID::text;

  IF para_Num_of_Pieces < 10 THEN
    UPDATE "member_attendance"
       SET "Num_of_Pieces" = "Num_of_Pieces" + para_Performance_ID
     WHERE "Num_of_Pieces" < var1;

    DELETE FROM "performance"
     WHERE "Attendance" = para_Attendance
       AND "integer" LIKE var2;

    UPDATE "performance"
       SET "Location" = CONCAT("Location", ':', var2)
     WHERE "Attendance" = para_Attendance;

    UPDATE "performance"
       SET "Host" = CONCAT("Host", ':', var2)
     WHERE "Attendance" >= var1;

  ELSIF para_Num_of_Pieces < 20 THEN
    FOR rec IN
      SELECT "Attendance", "integer"
        FROM "performance"
       WHERE "Attendance" > para_Attendance
    LOOP
      UPDATE "member_attendance"
         SET "Performance_ID" = rec."integer"
       WHERE "Num_of_Pieces" = rec."Attendance";
    END LOOP;

  ELSIF para_Num_of_Pieces < 30 THEN
    UPDATE "performance"
       SET "integer" = var2
     WHERE "Attendance" < para_Attendance;

    UPDATE "member_attendance"
       SET "Performance_ID" = CONCAT("Performance_ID", '_updated');

    DELETE FROM "performance"
     WHERE "Attendance" % 5 = 0;

  ELSIF para_Num_of_Pieces < 40 THEN
    IF para_Performance_ID > 50 THEN
      UPDATE "member_attendance"
         SET "Num_of_Pieces" = "Num_of_Pieces" / 2;
    ELSE
      UPDATE "member_attendance"
         SET "Num_of_Pieces" = "Num_of_Pieces" * 3;
    END IF;

    DELETE FROM "performance"
     WHERE "integer" IS NULL;

    INSERT INTO "performance" ("Attendance", "integer")
    VALUES (var1, 'fallback');

  ELSE
    INSERT INTO "performance" ("Attendance", "integer")
    VALUES (para_Attendance, para_integer);

    UPDATE "member_attendance"
       SET "Performance_ID" = 'final_state'
     WHERE "Num_of_Pieces" > 100;
  END IF;
END;
$$;

